# -*- coding: utf-8 -*-
"""Local mode: the same batches as h3run.py, generated by ComfyUI Desktop on this computer (port 8188).

No Colab, no colab-cli, no GPU to rent or release, no 15-minute keep. The job runner (remote/remote_job.py)
and the generation engine (H3 Toybox, headless) are the very same code the Colab mode uses; only the
servers they talk to are local.

  python h3local.py check                      ComfyUI up? models and nodes present? what is missing
  python h3local.py setup [--with-pictures]    download missing models, clone node packs and Toybox
  python h3local.py run <manifest.json> [--confirmed] [--force]

ComfyUI Desktop keeps models in C:\\Users\\<user>\\ComfyUI-Shared\\models by default. Whether a model is
there is asked from ComfyUI itself (/models/<folder>), so a file in any configured folder counts.
Videos default to 480P, like L4 on Colab.
"""
import argparse
import json
import os
import shutil
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
SKILL = HERE.parent
sys.path.insert(0, str(SKILL / "remote"))
sys.path.insert(0, str(HERE))
import remote_job as R                                                     # noqa: E402  model and node lists
from h3run import load_manifest, skip_finished, spec_summary              # noqa: E402

HOME = Path.home() / ".config" / "h3skill" / "local"
TOYBOX_REPO = HOME / "minimax-h3-colab"
T8 = HOME / "t8-enhancer"
DATA = HOME / "toybox_data"
TOYBOX_PORT = 8190
ENV = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")


def get(url, timeout=5):
    with urllib.request.urlopen(url, timeout=timeout) as r:
        return json.loads(r.read() or b"{}")


# ---------------------------------------------------------------- what this ComfyUI looks like
class Comfy:
    """Where this ComfyUI keeps things. ComfyUI Desktop starts main.py with --base-directory (and often
    --input-directory); a portable build gives only a relative main.py, so --comfy-dir fills the gap."""

    def __init__(self, url, models_dir=None, comfy_dir=None):
        self.url = url.rstrip("/")
        try:
            self.stats = get(self.url + "/system_stats")
        except Exception:
            self.stats = None
            return
        argv = self.stats.get("system", {}).get("argv", [])
        flag = lambda k: argv[argv.index(k) + 1] if k in argv and argv.index(k) + 1 < len(argv) else None
        main_py = Path(argv[0]) if argv else Path("main.py")
        base = comfy_dir or flag("--base-directory") or (main_py.parent if main_py.is_absolute() else None)
        self.base = Path(base) if base else None
        inp = flag("--input-directory") or (self.base / "input" if self.base else None)
        self.input = Path(inp) if inp else None
        shared = Path.home() / "ComfyUI-Shared" / "models"
        self.models = Path(models_dir) if models_dir else (
            shared if shared.is_dir() or not self.base else self.base / "models")
        self.custom_nodes = self.base / "custom_nodes" if self.base else None
        self._lists = {}

    @property
    def up(self):
        return self.stats is not None

    def listing(self, folder):
        """What ComfyUI itself sees in a model folder (all configured paths, subfolders included)."""
        if folder not in self._lists:
            try:
                self._lists[folder] = {Path(n.replace("\\", "/")).name for n in get(f"{self.url}/models/{folder}", 30)}
            except Exception:
                self._lists[folder] = set()  # a folder only a node pack registers, or not registered yet
        return self._lists[folder]

    def has_model(self, folder, name):
        name = Path(name).name
        return name in self.listing(folder) or (self.models / folder / name).is_file() or bool(
            self.base and (self.base / "models" / folder / name).is_file())

    def target(self, folder):
        return self.models / folder

    def python(self):
        """Toybox needs av and Pillow: ComfyUI Desktop's own venv (or the portable embedded one) has both."""
        if self.base:
            for p in (self.base / ".venv" / "Scripts" / "python.exe", self.base / ".venv" / "bin" / "python",
                      self.base.parent / "python_embeded" / "python.exe"):
                if p.is_file():
                    return str(p)
        return sys.executable


def needed(pictures):
    return R.BASE_MODELS + (R.PICTURE_MODELS if pictures else [])


def missing_models(c, pictures):
    return [(repo, f, folder) for repo, f, folder in needed(pictures) if not c.has_model(folder, f)]


def missing_nodes(c):
    """Every node class Toybox will submit must be known to this ComfyUI: the WF.json template minus the
    preview-only nodes Toybox strips (PREVIEW_ONLY), plus the nodes server.py builds itself (picture and
    prompt-rewrite graphs), plus the TTS graph. Missing core nodes mean ComfyUI is too old; missing others
    mean a node pack is not installed (or ComfyUI was not restarted)."""
    import re
    try:
        known = set(get(c.url + "/object_info", timeout=60))
    except Exception:
        return ["（讀不到 /object_info）"]
    toy = TOYBOX_REPO / "toybox"
    src = (toy / "server.py").read_text(encoding="utf-8") if (toy / "server.py").is_file() else ""
    m = re.search(r"PREVIEW_ONLY = \(([^)]*)\)", src)
    skip = set(re.findall(r'"([^"]+)"', m.group(1))) if m else set()
    want = set(re.findall(r'"class_type": "([A-Za-z0-9_]+)"', src))
    for wf, drop in ((toy / "WF.json", skip), (SKILL / "workflows" / "h3_tts32_api.json", set())):
        if wf.is_file():
            g = json.loads(wf.read_text(encoding="utf-8"))
            want |= {n["class_type"] for k, n in g.items() if isinstance(n, dict) and "class_type" in n and k not in drop}
    return sorted(want - known)


# ---------------------------------------------------------------- check / setup
def check(args, quiet=False):
    c = Comfy(args.comfy, args.models_dir, args.comfy_dir)
    if not c.up:
        print(f"❌ {args.comfy} 沒有回應：先打開 ComfyUI Desktop（要先安裝好：https://comfy.org/download）")
        return c, False
    dev = (c.stats.get("devices") or [{}])[0]
    vram = dev.get("vram_total", 0) / 2**30
    print(f"✅ ComfyUI {c.stats.get('system', {}).get('comfyui_version', '?')}　{dev.get('name', '?')}　VRAM {vram:.0f} GB")
    print(f"   模型資料夾：{c.models}")
    ok = True
    if not c.input:
        ok = False
        print("❌ 找不到 ComfyUI 的資料夾（input／custom_nodes 在哪）：加上 --comfy-dir <ComfyUI 資料夾>")
    if vram and vram < 15:
        print("⚠️ 顯示卡記憶體不到 16 GB：H3 可能跑不動，建議改用 Colab（h3run.py）")
    miss = missing_models(c, args.with_pictures)
    if miss:
        ok = False
        print(f"❌ 少 {len(miss)} 個模型：" + "、".join(Path(f).name for _, f, _ in miss))
    if not TOYBOX_REPO.is_dir():
        ok = False
        print("❌ 還沒下載 H3 Toybox（引擎）")
    else:
        nodes = missing_nodes(c)
        if nodes:
            ok = False
            print("❌ ComfyUI 不認得這些節點：" + "、".join(nodes))
            print("   （節點組沒裝、裝了還沒重開 ComfyUI，或 ComfyUI Desktop 太舊：先更新到最新版）")
    print("✅ 可以開始生成" if ok else "→ 執行 `python h3local.py setup`，照它說的做完、重開 ComfyUI Desktop，再 check 一次")
    return c, ok


def fetch(repo, name, dst):
    """Plain HTTP download with resume (no extra packages)."""
    url = f"https://huggingface.co/{repo}/resolve/main/{name}"
    part = dst.with_suffix(dst.suffix + ".part")
    dst.parent.mkdir(parents=True, exist_ok=True)
    have = part.stat().st_size if part.exists() else 0
    req = urllib.request.Request(url, headers={"Range": f"bytes={have}-"} if have else {})
    tok = os.environ.get("HF_TOKEN")
    if tok:
        req.add_header("Authorization", f"Bearer {tok}")
    with urllib.request.urlopen(req, timeout=60) as r, open(part, "ab" if have else "wb") as f:
        total = have + int(r.headers.get("Content-Length") or 0)
        t0, last = time.time(), 0
        while True:
            chunk = r.read(8 << 20)
            if not chunk:
                break
            f.write(chunk)
            have += len(chunk)
            if time.time() - last > 15:
                last = time.time()
                print(f"   {dst.name}  {have / 2**30:.1f}/{total / 2**30:.1f} GiB", flush=True)
    part.replace(dst)


def git_clone(url, dest):
    if Path(dest).is_dir():
        subprocess.run(["git", "-C", str(dest), "pull", "--ff-only"], check=False)
    else:
        subprocess.run(["git", "clone", "--depth", "1", url, str(dest)], check=True)


def setup(args):
    c = Comfy(args.comfy, args.models_dir, args.comfy_dir)
    if not c.up:
        sys.exit(f"❌ {args.comfy} 沒有回應：先打開 ComfyUI Desktop")
    HOME.mkdir(parents=True, exist_ok=True)
    print("① H3 Toybox（引擎）與提示詞技能庫")
    git_clone("https://github.com/dseditor/minimax-h3-colab.git", TOYBOX_REPO)
    git_clone("https://github.com/T8mars/comfyui-minimax-h3-prompt-enhancer-T8", T8)
    guides = TOYBOX_REPO / "toybox" / "guides"
    guides.mkdir(exist_ok=True)
    for g in ("VIDEO_PROMPT_WRITING_GUIDE_ref_en.md", "VIDEO_PROMPT_WRITING_GUIDE_base_en.md"):
        if not (guides / g).exists():
            fetch("MiniMaxAI/MiniMax-H3", "docs/" + g, guides / g)
    if not c.custom_nodes:
        sys.exit("❌ 找不到 ComfyUI 的資料夾：加上 --comfy-dir <ComfyUI 資料夾>（有 custom_nodes 的那一層）")
    print(f"② 節點組 → {c.custom_nodes}")
    new_nodes = []
    if not missing_nodes(c):  # already there, maybe under other folder names: cloning again would load them twice
        print("   ComfyUI 已經認得全部節點，不用裝")
    else:
        for name, url in R.NODES.items():
            d = c.custom_nodes / name
            if not d.is_dir():
                git_clone(url, d)
                new_nodes.append(d)
    miss = missing_models(c, args.with_pictures)
    print(f"③ 模型 → {c.models}（缺 {len(miss)} 個）")
    for repo, f, folder in miss:
        print(f"   下載 {Path(f).name}", flush=True)
        fetch(repo, f, c.target(folder) / Path(f).name)
    print("✅ 下載完成")
    if new_nodes:
        print("\n接下來（只有這一次）：")
        print(f"  1. 用 ComfyUI Desktop 自己的 Python 安裝節點的套件：")
        for d in new_nodes:
            if (d / "requirements.txt").is_file():
                print(f"     \"{c.python()}\" -m pip install -r \"{d / 'requirements.txt'}\"")
        print("  2. 重新啟動 ComfyUI Desktop")
        print("  3. python h3local.py check")


# ---------------------------------------------------------------- run
def start_toybox(c, pictures):
    try:
        get(f"http://127.0.0.1:{TOYBOX_PORT}/api/config", timeout=2)
        return None  # already up (an earlier run): reuse it
    except Exception:
        pass
    DATA.mkdir(parents=True, exist_ok=True)
    cfg_path = DATA / "config.json"
    cfg = json.loads(cfg_path.read_text(encoding="utf-8")) if cfg_path.exists() else {}
    have = all(c.has_model(folder, f) for _, f, folder in R.PICTURE_MODELS)
    cfg.update({"comfy_url": c.url, "comfy_input_dir": str(c.input),
                "skills_dir": str(T8 / "directional_skills"), "free_after_rewrite": True,
                "image": dict(cfg.get("image") or {}, engine="ph3", installed=have)})
    cfg.pop("guides", None)
    cfg_path.write_text(json.dumps(cfg, ensure_ascii=False, indent=1), encoding="utf-8")
    logf = open(HOME / "toybox.log", "w", encoding="utf-8")
    p = subprocess.Popen([c.python(), str(TOYBOX_REPO / "toybox" / "server.py")], cwd=str(TOYBOX_REPO / "toybox"),
                         env=dict(ENV, H3TOYBOX_PORT=str(TOYBOX_PORT), H3TOYBOX_DATA=str(DATA),
                                  H3TOYBOX_SECRETS=str(HOME / "secrets.json")),
                         stdout=logf, stderr=subprocess.STDOUT)
    for _ in range(30):
        try:
            get(f"http://127.0.0.1:{TOYBOX_PORT}/api/config", timeout=2)
            return p
        except Exception:
            time.sleep(1)
    p.kill()
    sys.exit("❌ H3 Toybox 沒有啟動：\n" + (HOME / "toybox.log").read_text(encoding="utf-8", errors="ignore")[-1500:])


def run(args):
    m, base = load_manifest(args.manifest)
    m = skip_finished(m, base, args.force)
    for j in m["jobs"]:
        if j["type"] == "video":
            j.setdefault("resolution", "480P")  # the creator: local defaults to 480P like L4
    vids = [j for j in m["jobs"] if j["type"] == "video"]
    print("這一批：" + spec_summary(m, "local"))
    if len(vids) >= 2 and not args.confirmed:
        sys.exit("兩支以上的影片：先把上面這行規格給使用者確認，確認後加 --confirmed 再跑")
    pictures = any(j["type"] == "image" for j in m["jobs"])
    args.with_pictures = pictures
    c, ok = check(args)
    if not ok:
        sys.exit(1)

    work = base / ".h3local"
    shutil.rmtree(work, ignore_errors=True)
    (work / "out").mkdir(parents=True)
    for j in m["jobs"]:  # the runner reads inputs/<path relative to the manifest>, like on Colab
        files = list(j.get("inputs", [])) + list(j.get("voices", [])) + [j.get(k) for k in ("first", "last", "extend")]
        for f in files:
            if f and not str(f).startswith("@") and (base / f).is_file():
                (work / "inputs" / f).parent.mkdir(parents=True, exist_ok=True)
                shutil.copy(base / f, work / "inputs" / f)
    (work / "manifest.json").write_text(json.dumps(m, ensure_ascii=False, indent=1), encoding="utf-8")
    shutil.copy(SKILL / "workflows" / "h3_tts32_api.json", work / "h3_tts32_api.json")

    toy = start_toybox(c, pictures)
    env = dict(ENV, H3JOB_LOCAL_TEST="1", H3JOB_FETCH="1", H3JOB_DIR=str(work), H3JOB_COMFY_URL=c.url,
               H3JOB_COMFY_INPUT=str(c.input), H3JOB_TOYBOX_URL=f"http://127.0.0.1:{TOYBOX_PORT}",
               H3JOB_TOYBOX_DATA=str(DATA))
    runner = subprocess.Popen([sys.executable, str(SKILL / "remote" / "remote_job.py")], env=env,
                              stdout=open(work / "runner.log", "w", encoding="utf-8"), stderr=subprocess.STDOUT)
    (base / "out").mkdir(exist_ok=True)
    seen, t0 = set(), time.time()
    try:
        while True:
            time.sleep(10)
            st = json.loads((work / "status.json").read_text(encoding="utf-8")) if (work / "status.json").exists() else {}
            for jid, s in st.get("jobs", {}).items():
                if s.get("status") in ("done", "error") and jid not in seen:
                    seen.add(jid)
                    if s["status"] == "done":
                        shutil.copy(work / "out" / s["file"], base / "out" / s["file"])
                        print(f"✅ {jid} → out/{s['file']}（{s.get('seconds_used')} 秒）", flush=True)
                    else:
                        print(f"❌ {jid}：{s.get('error')}", flush=True)
            if st.get("done") or runner.poll() is not None:
                break
            running = [k for k, s in st.get("jobs", {}).items() if s.get("status") == "running"]
            print(f"…{(time.time() - t0) / 60:.1f} 分鐘　{len(seen)}/{len(m['jobs'])} 完成　正在做：{', '.join(running) or '-'}",
                  flush=True)
    finally:
        if runner.poll() is None:
            runner.terminate()
        if toy:
            toy.terminate()
    res = {k: v for k, v in st.get("jobs", {}).items()}
    (base / "out" / "results.json").write_text(json.dumps(res, ensure_ascii=False, indent=1), encoding="utf-8")
    if st.get("error"):
        print("❌ 批次失敗：" + str(st["error"])[:1500])
        print(f"   完整紀錄：{work / 'runner.log'}、{HOME / 'toybox.log'}")
        sys.exit(1)
    print(f"完成：{sum(1 for v in res.values() if v.get('status') == 'done')}/{len(res)}，檔案在 {base / 'out'}")


def main():
    ap = argparse.ArgumentParser(description="H3 local mode (ComfyUI Desktop)")
    ap.add_argument("--comfy", default="http://127.0.0.1:8188")
    ap.add_argument("--models-dir", help="下載到哪裡。預設 ~/ComfyUI-Shared/models（ComfyUI Desktop），沒有就用 ComfyUI 的 models")
    ap.add_argument("--comfy-dir", help="ComfyUI 的資料夾（有 input、custom_nodes 的那一層）；Desktop 會自己回報，通常不用填")
    sub = ap.add_subparsers(dest="cmd", required=True)
    c = sub.add_parser("check")
    c.add_argument("--with-pictures", action="store_true")
    s = sub.add_parser("setup")
    s.add_argument("--with-pictures", action="store_true", help="也下載生圖模型（約多 10 GB）")
    r = sub.add_parser("run")
    r.add_argument("manifest")
    r.add_argument("--confirmed", action="store_true")
    r.add_argument("--force", action="store_true")
    args = ap.parse_args()
    if args.cmd == "check":
        sys.exit(0 if check(args)[1] else 1)
    {"setup": setup, "run": run}[args.cmd](args)


if __name__ == "__main__":
    main()
